# Parse the graph from context
edges = context.strip().split('\n')
graph = {}

for edge in edges:
    if ' -> ' in edge:
        src, dst = edge.split(' -> ')
        if src not in graph:
            graph[src] = []
        graph[src].append(dst)

# Now graph is a dict: node -> list of outgoing neighbors
print(f"Graph parsed. Total nodes: {len(graph)}")
print(f"Example: graph['1679091c5a'] = {graph.get('1679091c5a', [])}")

from collections import deque

start_node = "1679091c5a"
target_depth = 4

# BFS
visited = set()
queue = deque([(start_node, 0)])
depth_nodes = {0: [start_node]}

while queue:
    node, depth = queue.popleft()

    if node in visited:
        continue
    visited.add(node)

    # If we're at the target depth, we don't go further
    if depth == target_depth:
        continue

    # Explore neighbors
    if node in graph:
        for neighbor in graph[node]:
            if neighbor not in visited:
                queue.append((neighbor, depth + 1))
                if depth + 1 not in depth_nodes:
                    depth_nodes[depth + 1] = []
                depth_nodes[depth + 1].append(neighbor)

# Get nodes at exactly depth 4
result = depth_nodes.get(target_depth, [])
print(f"Nodes at depth 4: {result}")
